sys_script_include.script:
var EbondingExampleImpl = Class.create();

EbondingExampleImpl.prototype = {
   initialize : function() {
   },

   /**
	* Generate the ebonding files
	* @param GlideRecord ebondingConfig The ebonding configuration object
    */
   generate : function(ebondingConfig) {
		gs.info("EbondingExampleImpl.generate() START generating ebonding files...");

		// Create a new business rule

      var grBusinessRule = new GlideRecord("sys_script");
      grBusinessRule.initialize();
      grBusinessRule.name = "EbondingExampleBR";
      grBusinessRule.collection = "incident";
      grBusinessRule.script = "gs.info('EbondingExampleBR');";
      grBusinessRule.when = "before";
      grBusinessRule.action_insert = true;
      grBusinessRule.active = true;
      grBusinessRule.insert();


		return true;
   }

}
